var RX_BODY = window.RX_BODY || {};

RX_BODY['ketamine'] = {
  what: {
    ar: 'الكيتامين مخدّر عام يُعطى في المستشفى بالحقن في الوريد أو العضل، ويُسمّى «مخدّراً انفصالياً» لأنه يفصل المريض عن إحساسه بما حوله أكثر مما ينيمه نوماً عادياً. يمنح تسكيناً قوياً للألم ونسياناً لما جرى، ويتميّز عن أغلب المخدّرات بأنه يحفظ التنفّس وردود فعل الحلق في الغالب ويرفع ضغط الدم بدل أن يخفضه. وهو مادة خاضعة للرقابة لأنه يُساء استعماله في الشارع، ومنه شقيق قريب يُسمّى الإسكيتامين معتمد لعلاج الاكتئاب مع مضادّات الاكتئاب الفموية.',
    en: 'Ketamine is a general anaesthetic given in hospital by injection into a vein or muscle. It is called a “dissociative” anaesthetic because it cuts the patient off from awareness of their surroundings rather than producing ordinary sleep. It gives strong pain relief and loss of memory of the event, and unlike most anaesthetics it usually preserves breathing and throat reflexes and raises blood pressure instead of lowering it. It is a controlled substance because it is misused on the street, and a close relative called esketamine is approved for depression alongside oral antidepressants.'
  },
  why: {
    ar: 'يُستعمل مخدّراً وحده في الإجراءات القصيرة التي لا تحتاج إرخاء العضلات، أو مقدّمةً للتخدير العام مع أدوية أخرى. وفي الطوارئ يُختار كثيراً للتهدئة أثناء ردّ الكسور والخلوع وتصريف الخرّاجات وخياطة جروح الأطفال، ولإدخال أنبوب التنفّس خصوصاً لمن عنده تشنّج قصبي لأنه يوسّع الشعب. وتُستعمل مقادير صغيرة منه مع المسكّنات الأخرى لآلام الإصابات والكسور والبطن والظهر. ويلجأ إليه الأطباء خارج النشرة في نوبات الصرع المستمرّة التي لم تستجب لغيره، وفي الاكتئاب المقاوم للعلاج والأفكار الانتحارية ضمن برامج متخصّصة.',
    en: 'It is used as the sole anaesthetic for short procedures that do not need muscle relaxation, or to start general anaesthesia together with other drugs. In emergency care it is often chosen for sedation while fractures and dislocations are set, abscesses drained and children’s wounds stitched, and for placing a breathing tube, especially in patients with bronchospasm because it widens the airways. Small amounts are used alongside other painkillers for pain from injuries, fractures, the abdomen and the back. Doctors also use it off-label for continuous seizures that have not responded to other drugs, and for treatment-resistant depression and suicidal thoughts within specialised programmes.'
  },
  how: {
    ar: 'في الدماغ مستقبلات تُسمّى NMDA تستقبل ناقلاً عصبياً منبّهاً هو الغلوتامات، وعبرها تمرّ إشارات الألم والوعي. يسدّ الكيتامين هذه المستقبلات فينقطع الاتصال بين مناطق الدماغ التي تبني الإحساس بالجسد والمكان، فيدخل المريض حالة قد تبقى فيها عيناه مفتوحتين لكنه لا يشعر ولا يتذكّر. وفي الوقت نفسه ينبّه الجهازين القلبي والتنفّسي بدل أن يثبّطهما، فلا يهبط الضغط كما مع غيره. ويرى الباحثون أن أثره في الاكتئاب والألم المزمن يدوم بعد خروجه من الجسم لأنه يقوّي الروابط بين مناطق الدماغ ويرفع مادة تغذّي الخلايا العصبية.',
    en: 'The brain has receptors called NMDA that receive an excitatory messenger, glutamate, and pain and awareness signals travel through them. Ketamine blocks these receptors, cutting the connection between the brain regions that build the sense of body and place, so the patient enters a state in which the eyes may stay open but they feel nothing and remember nothing. At the same time it stimulates the heart and breathing instead of depressing them, so blood pressure does not fall as it does with other agents. Researchers believe its effect on depression and chronic pain outlasts its presence in the body because it strengthens connections between brain regions and raises a substance that nourishes nerve cells.'
  },
  effects: {
    ar: 'أشهر ما يلاحظه المريض بعد الإفاقة الغثيان والقيء والدوخة والنعاس وشعور غير مريح بالانفصال أو الكآبة. ويمرّ بعض المرضى بما يُسمّى «تفاعلات الإفاقة»: أحلام حيّة أو هلاوس أو ارتباك أو خوف شديد أو تصرّف غير معتاد أو أرق، وقد تعود ومضات منها لاحقاً. ويرتفع الضغط والنبض مؤقتاً، وتزيد إفرازات اللعاب، وقد تظهر رؤية مزدوجة أو حركة لا إرادية في العينين أو تيبّس وتقلّص في العضلات. وأغلب ذلك يزول بزوال الدواء، ولهذا يبقى المريض تحت المراقبة حتى يعود إلى وعيه المعتاد قبل خروجه.',
    en: 'The most common things patients notice on waking are nausea, vomiting, dizziness, drowsiness and an unpleasant feeling of detachment or low mood. Some go through what are called “emergence reactions”: vivid dreams, hallucinations, confusion, intense fear, unusual behaviour or insomnia, and flashbacks of them may return later. Blood pressure and pulse rise for a while, saliva increases, and double vision, involuntary eye movements or muscle stiffness and spasms may appear. Most of this fades as the drug wears off, which is why the patient stays under observation until back to their usual state of mind before going home.'
  },
  warning: {
    ar: 'لا يُعطى إلا بيد فريق مجهّز لإدخال أنبوب التنفّس، فالمراقبة داخل المستشفى خط الأمان الأول. بعد الخروج لا تقد السيارة ولا تشغّل آلات ولا تقم بعمل خطر يوماً كاملاً، ولا تبق وحدك، ولا تشرب الكحول. اطلب الإسعاف فوراً إن ظهر ضيق نفس أو ازرقاق أو ألم في الصدر أو نبض سريع غير منتظم أو تشنّج أو تورّم في الوجه والحلق أو ارتباك وهلاوس لا تهدأ. وراجع الطبيب إن ظهر اصفرار في الجلد أو العينين. ومن تكرّر تعاطيه خارج الإشراف ثم ظهر عنده ألم عند التبوّل أو دم في البول أو إلحاح متكرّر فتلك علامات أذى في المثانة تستوجب التوقّف والمراجعة.',
    en: 'It is given only by a team equipped to place a breathing tube, so in-hospital monitoring is the first line of safety. After going home, do not drive, operate machinery or do anything hazardous for a full day, do not stay alone and do not drink alcohol. Call an ambulance at once for breathlessness, blue lips, chest pain, a fast irregular pulse, a seizure, swelling of the face and throat, or confusion and hallucinations that do not settle. See a doctor for yellowing of the skin or eyes. Anyone who has used it repeatedly outside supervision and then develops pain on passing urine, blood in the urine or constant urgency has signs of bladder damage that require stopping and seeing a doctor.'
  },
  interact: {
    ar: 'أخطر تعارضاته مع كل ما يثبّط الجهاز العصبي: الأفيونات والبنزوديازيبينات والمنوّمات والكحول؛ فاجتماعها قد يسبّب تهدئة عميقة وتثبيطاً للتنفّس وغيبوبة وقد يكون قاتلاً، والكحول بالذات خطير عند من يتعاطى الكيتامين. وقد تزيد الأدوية المنبّهة الشبيهة بالأدرينالين والفازوبريسين أثره في رفع الضغط والنبض. ويخفض الثيوفيلين والأمينوفيلين عتبة التشنّج إذا اجتمعا معه، ولا يُجمع مع مثبّطات الأكسيداز أحادي الأمين. أخبر فريق التخدير بكل أدويتك ومكمّلاتك وبأي تعاطٍ حديث للكحول أو المخدّرات، فالصراحة هنا جزء من سلامتك.',
    en: 'Its most dangerous interactions are with anything that depresses the nervous system: opioids, benzodiazepines, sleeping pills and alcohol; together they can cause deep sedation, suppressed breathing, coma and possibly death, and alcohol is especially dangerous in people who use ketamine. Adrenaline-like stimulant drugs and vasopressin may increase its effect on blood pressure and pulse. Theophylline and aminophylline lower the seizure threshold when combined with it, and it is not combined with monoamine oxidase inhibitors. Tell the anaesthetic team about all your medicines and supplements and any recent alcohol or drug use, because honesty here is part of your safety.'
  },
  avoid: {
    ar: 'يُتجنّب عند من يشكّل ارتفاع الضغط خطراً عليه: ضغط غير مسيطر عليه، أو تسلّخ الأبهر، أو تمدّد الشرايين، أو احتشاء قلبي، وعند من سبق أن تحسّس منه، ومن لديه فصام قد يسوء به، ومن يأخذ مثبّطات الأكسيداز. ولا يُنصح به في الحمل لنقص أدلّة الأمان إلا في طوارئ الولادة حين لا يتوفّر التخدير النصفي، ولا يُنصح به في الرضاعة وإن كانت كميّته في الحليب قليلة. وتحذّر هيئة الدواء الأمريكية من أن التخدير الطويل أو المتكرّر للأطفال دون الثالثة وللحوامل في الثلث الأخير قد يؤثّر في نموّ الدماغ، فيُناقَش توقيت العمليات غير العاجلة دون تأخير الضروري منها. والمسنّون يستقلبونه أبطأ.',
    en: 'It is avoided in people for whom a rise in blood pressure is dangerous: uncontrolled high blood pressure, aortic dissection, aneurysms or a heart attack, and in anyone previously allergic to it, anyone with schizophrenia that it may worsen, and anyone taking monoamine oxidase inhibitors. It is not recommended in pregnancy because safety evidence is lacking, except in obstetric emergencies when spinal anaesthesia is unavailable, and not recommended in breastfeeding although little reaches the milk. The US FDA warns that lengthy or repeated anaesthesia in children under three and in women in the third trimester may affect brain development, so the timing of non-urgent operations is discussed without delaying necessary ones. Older people break it down more slowly.'
  },
  updated: '2026-09-11',
  src: [
    'https://www.ncbi.nlm.nih.gov/books/NBK470357/',
    'https://www.ncbi.nlm.nih.gov/books/NBK541087/',
    'https://www.ncbi.nlm.nih.gov/books/NBK551685/',
    'https://www.accessdata.fda.gov/drugsatfda_docs/label/2017/016812s043lbl.pdf'
  ]
};

RX_BODY['propofol'] = {
  what: {
    ar: 'البروبوفول مخدّر عام يُحقن في الوريد، وهو من أكثر ما يُستعمل اليوم لبدء التخدير العام وللتهدئة أثناء المناظير والإجراءات. يُعرف بلونه الأبيض الحليبي لأنه مذاب في مستحلب دهني يحتوي زيت الصويا ومادة من صفار البيض، وهذا المستحلب يصلح وسطاً لنموّ الجراثيم فلا بدّ من تحضيره بتعقيم صارم. يعمل خلال ثوانٍ ويزول أثره سريعاً فيستيقظ المريض عادةً بسرعة، لكنه لا يسكّن الألم بذاته، ولهذا يُجمع غالباً مع مسكّن. يعطيه أطباء التخدير والعناية المركّزة وحدهم.',
    en: 'Propofol is a general anaesthetic injected into a vein, and today it is one of the most used drugs to start general anaesthesia and for sedation during endoscopy and procedures. It is known for its milky white colour because it is dissolved in a fat emulsion containing soybean oil and a substance from egg yolk, and this emulsion can support the growth of germs, so it must be prepared with strict sterile technique. It acts within seconds and wears off quickly, so the patient usually wakes fast, but it does not relieve pain by itself, which is why it is usually combined with a painkiller. Only anaesthesia and intensive care teams give it.'
  },
  why: {
    ar: 'يُستعمل لبدء التخدير العام قبل العمليات، ولإبقاء التخدير مستمراً بالتسريب، وللتهدئة أثناء المناظير وردّ الكسور والخلوع وتصريف الخرّاجات والصدمة الكهربائية لتنظيم نبض القلب والتصوير عند من لا يستطيع الثبات. ويُستعمل في العناية المركّزة لتهدئة المرضى على أجهزة التنفّس. ومن استعمالاته خارج النشرة إيقاف نوبات الصرع المستمرّة التي لم تستجب للأدوية الأولى، وعلاج الغثيان والقيء بعد العمليات. وهو الخيار المفضّل لبدء التخدير العام عند الحامل المستقرّة حين تحتاج عملية تحت التخدير العام.',
    en: 'It is used to start general anaesthesia before operations, to keep anaesthesia going by infusion, and for sedation during endoscopy, setting fractures and dislocations, draining abscesses, electrical cardioversion of the heart rhythm and imaging in people who cannot keep still. In intensive care it sedates patients on breathing machines. Off-label uses include stopping continuous seizures that have not responded to first-line drugs and treating nausea and vomiting after surgery. It is the preferred drug to start general anaesthesia in a stable pregnant woman who needs an operation under general anaesthesia.'
  },
  how: {
    ar: 'في الدماغ ناقل عصبي مهدّئ اسمه «غابا» يفتح قنوات تُدخل الكلوريد إلى الخلايا العصبية فتهدأ. يقوّي البروبوفول أثر الغابا على مستقبلاته ويطيل فتح هذه القنوات، فتصبح الخلايا أقلّ قدرة على إطلاق إشاراتها، فينتقل المريض من الاسترخاء إلى النوم ثم إلى فقدان الوعي بحسب الكمية. ولأنه يذوب في الدهون يصل إلى الدماغ خلال ثوانٍ، ثم يتوزّع في أنسجة الجسم ويتفكّك، فيستيقظ المريض سريعاً عند إيقافه. وهو يوسّع الأوعية الدموية ويضعف انقباض القلب، ومن هنا هبوط الضغط الذي يرافقه.',
    en: 'The brain has a calming messenger called GABA that opens channels letting chloride into nerve cells so they quieten. Propofol strengthens GABA’s action on its receptors and keeps these channels open longer, so the cells become less able to fire their signals, and the patient passes from relaxation to sleep and then to unconsciousness depending on the amount. Because it dissolves in fat it reaches the brain within seconds, then spreads into body tissues and is broken down, so the patient wakes quickly when it is stopped. It widens blood vessels and weakens the heart’s contraction, which explains the fall in blood pressure that comes with it.'
  },
  effects: {
    ar: 'أشيع ما يشعر به المريض ألم أو لسع في الوريد لحظة إعطائه. ويهبط ضغط الدم عادةً بعده، ويبطؤ التنفّس أو يتوقّف مؤقتاً، وهذا ما يديره فريق التخدير بالمراقبة والأكسجين ومعدّات التنفّس. وقد تظهر حركات عضلية ارتجافية قصيرة لا تعني تشنّجاً. وبعد التخدير العام يشيع النعاس وألم الحلق من أنبوب التنفّس والرعشة والغثيان وشيء من التشوّش المؤقّت، ويزول أغلبها خلال ساعات. ومن النادر أن يتلوّن البول بالأخضر، أو أن يحدث اضطراب في تخطيط القلب أو التهاب في البنكرياس أو تشنّج في الشعب عند مرضى الربو.',
    en: 'The most common thing the patient feels is pain or stinging in the vein at the moment it is given. Blood pressure usually falls afterwards and breathing slows or stops for a while, which the anaesthetic team manages with monitoring, oxygen and airway equipment. Brief jerking muscle movements may occur and do not mean a seizure. After general anaesthesia, drowsiness, a sore throat from the breathing tube, shivering, nausea and some temporary confusion are common and mostly pass within hours. Rarely the urine turns green, or a change on the heart tracing, inflammation of the pancreas or airway spasm in people with asthma occurs.'
  },
  warning: {
    ar: 'يُعطى داخل المستشفى فقط بوجود فريق مدرّب وأجهزة مراقبة ومعدّات إنعاش. بعد الخروج من التخدير العام لا تقد السيارة ولا تشغّل آلات ولا تتّخذ قرارات مهمّة ولا تشرب الكحول ولا ترع أطفالاً وحدك يوماً كاملاً، وليكن معك شخص بالغ. اطلب الطوارئ إن ظهر ضيق نفس أو ازرقاق أو تورّم في الوجه والحلق أو طفح واسع، أو ألم شديد في أعلى البطن مع قيء. ومن كان قريبه في العناية المركّزة على تسريب طويل منه فليعلم أن الفريق يراقب متلازمة نادرة خطيرة تسبّب حموضة الدم وارتفاع البوتاسيوم والدهون وتحلّل العضلات، وعلاجها إيقاف الدواء فوراً.',
    en: 'It is given only in hospital with a trained team, monitors and resuscitation equipment. After general anaesthesia, do not drive, operate machinery, make important decisions, drink alcohol or look after children alone for a full day, and have an adult with you. Seek emergency care for breathlessness, blue lips, swelling of the face and throat or a widespread rash, or severe upper abdominal pain with vomiting. Anyone whose relative is in intensive care on a long infusion should know the team watches for a rare, serious syndrome causing acid blood, high potassium and blood fats, and muscle breakdown, which is treated by stopping the drug at once.'
  },
  interact: {
    ar: 'يتضاعف أثره المثبّط للتنفّس والدورة الدموية مع الأفيونات والبنزوديازيبينات وسائر المهدّئات والمنوّمات، ولهذا تُضبط الكميّات حين تُجمع، وهو ما يحدث عمداً في أغلب العمليات تحت مراقبة. ويُحتاط معه مع الأدوية التي تطيل فترة QT في تخطيط القلب. ويزيد البروبوفول استجابة الضغط للإيفيدرين إذا أُعطي لرفع الضغط. والكحول قبل العملية أو بعدها يزيد النعاس والتشوّش، فامتنع عنه. أخبر فريق التخدير قبل العملية بكل أدويتك، بما فيها المسكّنات والمنوّمات وأدوية القلب والأعشاب، وبأي حساسية سابقة من الأدوية أو الأطعمة.',
    en: 'Its depressant effect on breathing and circulation is multiplied by opioids, benzodiazepines and other sedatives and sleeping pills, which is why amounts are adjusted when they are combined, as happens deliberately in most operations under monitoring. Caution is needed with drugs that prolong the QT interval on the heart tracing. Propofol increases the blood-pressure response to ephedrine when that is given to raise pressure. Alcohol before or after the operation adds to drowsiness and confusion, so avoid it. Before the operation tell the anaesthetic team about all your medicines, including painkillers, sleeping pills, heart drugs and herbal products, and about any previous allergy to medicines or foods.'
  },
  avoid: {
    ar: 'لا يُعطى لمن تحسّس منه سابقاً، ويُتجنّب أو يُحتاط معه عند هبوط الضغط الشديد أو نقص حجم الدم كالنزيف غير المعوّض. ومن عنده حساسية من البيض أو الصويا مع ميل عام للتحسّس فليخبر طبيب التخدير، فالحساسية تنشأ من البروتينات لا من الدهون، والقرار يعود لتقديره. وهو معتمد للأطفال من سنّ الثالثة ويُستعمل لمن هم أصغر بحسب الحاجة، وتشمله تحذيرات هيئة الدواء الأمريكية من التخدير الطويل أو المتكرّر للأطفال دون الثالثة وللحامل في الثلث الأخير. وفي الحمل هو المفضّل لبدء التخدير العام، مع احتمال نعاس المولود وضعف تنفّسه إن أُعطي قرب الولادة.',
    en: 'It is not given to anyone previously allergic to it, and it is avoided or used with caution in severe low blood pressure or low blood volume, such as uncorrected bleeding. Anyone with an egg or soy allergy and a general tendency to allergies should tell the anaesthetist, because allergy comes from proteins rather than the fats, and the decision is theirs. It is approved for children from three years of age and used in younger children when needed, and it falls under the US FDA warnings about lengthy or repeated anaesthesia in children under three and in the third trimester of pregnancy. In pregnancy it is preferred to start general anaesthesia, with a chance of a drowsy newborn with weak breathing if given close to delivery.'
  },
  updated: '2026-09-11',
  src: [
    'https://www.ncbi.nlm.nih.gov/books/NBK430884/',
    'https://www.ncbi.nlm.nih.gov/books/NBK551685/',
    'https://www.ncbi.nlm.nih.gov/books/NBK547661/',
    'https://www.nhs.uk/tests-and-treatments/general-anaesthesia/',
    'https://www.accessdata.fda.gov/drugsatfda_docs/label/2017/016812s043lbl.pdf'
  ]
};

RX_BODY['bupivacaine'] = {
  what: {
    ar: 'البوبيفاكايين مخدّر موضعي من فصيلة الأميدات، أي من عائلة الليدوكايين نفسها، لكنه أبطأ بدءاً وأطول أثراً بكثير. لا يُباع للعامّة ولا يُدهن على الجلد، بل يحقنه طبيب التخدير أو الجرّاح أو طبيب الأسنان قرب الأعصاب أو في الظهر ليفقد جزء من الجسم إحساسه بالألم ساعات طويلة والمريض مستيقظ. ومنه صيغة تُحقن في السائل الشوكي للتخدير النصفي، وصيغة داخل كريّات دهنية دقيقة تتحرّر ببطء لتسكين ألم ما بعد العملية أياماً. وهو أشدّ مخدّرات فصيلته أذى على القلب إذا وصل الدم بكمية كبيرة.',
    en: 'Bupivacaine is a local anaesthetic of the amide class, the same family as lidocaine, but slower to start and much longer lasting. It is not sold to the public and not applied to the skin; an anaesthetist, surgeon or dentist injects it near nerves or into the back so that part of the body loses pain sensation for many hours while the patient stays awake. There is a form injected into the spinal fluid for spinal anaesthesia and a form packed inside tiny fat spheres that release it slowly to relieve pain for days after surgery. It is the most harmful to the heart in its class if a large amount reaches the bloodstream.'
  },
  why: {
    ar: 'يُستعمل للتخدير النصفي (الشوكي)، وللإبرة فوق الجافية (الإيبيدورال) لتسكين ألم الولادة، وللتخدير في العمليات القيصرية، ولتخدير عصب بعينه أو ضفيرة أعصاب فيخدر ذراع أو ساق كاملة، وللحقن الموضعي في موضع الجراحة. وهو مفيد خصوصاً حين يحتاج الإجراء إحصاراً طويلاً للإحساس والحركة، ولتسكين ألم ما بعد العمليات فتقلّ الحاجة إلى المسكّنات القوية بعد الاستيقاظ. وفي طبّ الأسنان يُختار للإجراءات الطويلة وجراحات الفم كخلع ضروس العقل المنطمرة، ولتسكين ما بعدها، لأن أثره في الأنسجة يمتدّ ساعات أطول من الليدوكايين.',
    en: 'It is used for spinal anaesthesia, for epidurals to relieve labour pain, for anaesthesia during caesarean sections, for blocking a single nerve or a nerve plexus so a whole arm or leg goes numb, and for local injection at the surgical site. It is especially useful when a procedure needs a long block of sensation and movement, and for pain after surgery, reducing the need for strong painkillers on waking. In dentistry it is chosen for long procedures and oral surgery such as removing impacted wisdom teeth, and for pain afterwards, because its effect in the tissues lasts hours longer than lidocaine.'
  },
  how: {
    ar: 'تنتقل إشارة الألم في العصب بتيار كهربائي يعتمد على قنوات دقيقة تُدخل الصوديوم إلى الليف العصبي. يلتصق البوبيفاكايين بهذه القنوات ويغلقها، فلا تمرّ الإشارة من موضع الحقن إلى الدماغ، ويفقد الجزء الذي يغذّيه العصب إحساسه، وقد تضعف حركته أيضاً. ويتميّز بأنه يبقى ملتصقاً بالقنوات مدّة طويلة ولا يفارقها بسهولة، وهذا سرّ طول أثره، لكنه أيضاً سرّ خطره: فالقلب يعمل بقنوات الصوديوم نفسها، وإذا وصله الدواء بكمية كبيرة التصق بها فاضطرب نظمه وضعف انقباضه، ويفكّكه الكبد ببطء.',
    en: 'Pain signals travel along a nerve as an electrical current that depends on tiny channels letting sodium into the nerve fibre. Bupivacaine sticks to these channels and closes them, so the signal cannot pass from the injection site to the brain, and the part supplied by that nerve loses sensation and may also lose strength. Its distinctive feature is that it stays attached to the channels for a long time and lets go reluctantly, which is the secret of its long action but also of its danger: the heart runs on the same sodium channels, and if a large amount reaches it the drug clings to them, disturbing the rhythm and weakening the beat. The liver breaks it down slowly.'
  },
  effects: {
    ar: 'ما يُتوقّع بعد الحقن هو الخدر نفسه وثقل الطرف أو ضعفه، ثم وخز أو حرقة خفيفة حين يبدأ الأثر بالزوال. وقد يظهر ألم أو كدمة صغيرة في موضع الإبرة، وقد يشعر بعض الناس بصداع أو دوخة أو تشوّش رؤية عابر. ومع التخدير النصفي أو الإيبيدورال يشيع هبوط ضغط الدم لأن الأوعية في الجزء المخدَّر تتوسّع، ويعالجه الفريق بالسوائل وبأدوية رافعة للضغط مثل الإيفيدرين، وهو شائع خصوصاً عند الحوامل. هذه آثار يتوقّعها الفريق ويراقبها، وتختفي بانتهاء مفعول الدواء.',
    en: 'What is expected after the injection is the numbness itself and heaviness or weakness of the limb, then mild tingling or burning as it starts to wear off. There may be pain or a small bruise at the needle site, and some people feel a passing headache, dizziness or blurred vision. With spinal or epidural anaesthesia a fall in blood pressure is common because blood vessels in the numbed part widen, and the team treats it with fluids and pressure-raising drugs such as ephedrine; it is especially common in pregnant women. These are effects the team expects and monitors, and they vanish when the drug wears off.'
  },
  warning: {
    ar: 'أخبر الطبيب أو الممرّضة فوراً، أثناء الحقن أو بعده، إن شعرت بخدر أو تنميل حول الشفتين أو الفم، أو طعم معدني، أو طنين في الأذنين، أو رؤية مشوّشة، أو دوخة، أو رجفة، أو ثقل في الكلام، أو إحساس غامر بأن شيئاً سيئاً سيحدث؛ فهذه أولى علامات تسمّم الدم بالمخدّر الموضعي، وقد تتبعها نوبة تشنّج واضطراب نظم القلب وتوقّفه. ولهذا يُحقن على دفعات مع السحب قبل الحقن والمراقبة، ويتوفّر علاج إسعافي بمستحلب دهني. وبعد الخروج احم الطرف المخدَّر من الحرق والصدمات والضغط لأنك لن تشعر بالأذى، ولا تأكل حتى يعود الإحساس إلى الفم.',
    en: 'Tell the doctor or nurse immediately, during or after the injection, if you feel numbness or tingling around the lips or mouth, a metallic taste, ringing in the ears, blurred vision, dizziness, trembling, slurred speech or an overwhelming feeling that something bad is about to happen; these are the first signs of local anaesthetic poisoning of the blood, which may be followed by a seizure, heart rhythm disturbance and cardiac arrest. That is why it is injected in stages, with aspiration before injecting and monitoring, and an emergency treatment with a fat emulsion is available. After going home, protect the numb limb from burns, knocks and pressure because you will not feel the injury, and do not eat until feeling returns to the mouth.'
  },
  interact: {
    ar: 'يتراكم خطره حين يُجمع مع مخدّرات موضعية أخرى في الجلسة نفسها، لأن سمّيتها تُحسب مجتمعة، فلا يُضاف إليه كريم أو حقنة مخدّرة دون علم الطبيب. ويتداخل مع أدوية الإرغوت ومميّعات الدم وبعض مضادّات الاكتئاب، فيجب أن يعرفها الطبيب قبل الحقن، خصوصاً قبل إبر الظهر. ويزيد خطر حالة نادرة تُسمّى «الميتهيموغلوبينية»، يعجز فيها الدم عن حمل الأكسجين، مع النترات وبعض المضادّات الحيوية ومضادّات الملاريا ومضادّات الصرع. أخبر فريق التخدير بكل أدويتك قبل أي تخدير موضعي أو نصفي.',
    en: 'Its danger adds up when combined with other local anaesthetics in the same session, because their toxicity counts together, so no numbing cream or injection should be added without the doctor knowing. It interacts with ergot medicines, blood thinners and some antidepressants, which the doctor must know about before the injection, especially before back injections. It raises the risk of a rare condition called methaemoglobinaemia, in which the blood cannot carry oxygen, with nitrates, some antibiotics, antimalarials and anti-seizure drugs. Tell the anaesthetic team about all your medicines before any local or spinal anaesthetic.'
  },
  avoid: {
    ar: 'لا يُعطى لمن تحسّس منه أو من مخدّرات الأميد، ولا يُحقن في موضع فيه عدوى. وتمنع النشرة الرسمية تركيزه الأعلى في تخدير الولادة بعد حالات نادرة من توقّف القلب، وتمنع استعماله في تخدير الطرف عبر الوريد، وفي حقنه جانب عنق الرحم أثناء الولادة، وفي التسريب المستمرّ داخل المفصل. ويُحتاط معه في أمراض الكبد المتوسّطة والشديدة لأن الكبد يفكّكه، وفي أمراض القلب، وعند المسنّين، والرضّع دون ستة أشهر أكثر حساسية له. وهو يعبر المشيمة ويُستعمل في الولادة بتركيزاته الأدنى، ولا يمنع الرضاعة التي تُستأنف بعد تعافي الأم.',
    en: 'It is not given to anyone allergic to it or to amide anaesthetics, and it is not injected into an infected site. The official label forbids its highest concentration for obstetric anaesthesia after rare cases of cardiac arrest, and forbids it for intravenous regional anaesthesia of a limb, for paracervical block during labour and for continuous infusion into a joint. Caution is needed in moderate or severe liver disease because the liver breaks it down, in heart disease and in older people, and infants under six months are more sensitive to it. It crosses the placenta and is used in labour at its lower concentrations, and it does not prevent breastfeeding, which resumes once the mother has recovered.'
  },
  updated: '2026-09-11',
  src: [
    'https://www.ncbi.nlm.nih.gov/books/NBK532883/',
    'https://www.ncbi.nlm.nih.gov/books/NBK499964/',
    'https://www.ncbi.nlm.nih.gov/books/NBK610935/',
    'https://www.ncbi.nlm.nih.gov/books/NBK547661/',
    'https://www.nhs.uk/tests-and-treatments/local-anaesthesia/'
  ]
};

RX_BODY['lidocaine'] = {
  what: {
    ar: 'الليدوكايين أكثر المخدّرات الموضعية استعمالاً في العالم، والمرجع الذي يُقاس عليه غيره. ينتمي إلى فصيلة الأميدات، ويأتي بأشكال كثيرة: حقن يعطيها الطبيب أو طبيب الأسنان، وكريمات ومراهم وجل وبخّاخ ولصقات للجلد أو الأغشية، ومحلول لزج للفم والحلق، ومحاليل لتخدير المجاري التنفّسية قبل المناظير. وله وجه ثانٍ لا يعرفه كثيرون: فهو أيضاً دواء لاضطرابات نظم القلب البطينية يُحقن في الوريد في الطوارئ والعناية. ومنه تركيبة مع الأدرينالين لها بطاقتها الخاصة في هذه الموسوعة.',
    en: 'Lidocaine is the most widely used local anaesthetic in the world and the standard against which others are measured. It belongs to the amide class and comes in many forms: injections given by a doctor or dentist, creams, ointments, gels, sprays and patches for the skin or membranes, a viscous solution for the mouth and throat, and solutions to numb the airways before endoscopy. It has a second face few people know: it is also a treatment for ventricular heart rhythm disorders, injected into a vein in emergencies and intensive care. A combination with adrenaline has its own card in this encyclopaedia.'
  },
  why: {
    ar: 'يُستعمل لتخدير موضع صغير قبل خياطة جرح أو إجراء جراحي بسيط، ولتخدير الأسنان قبل الحشو والعلاج، ولتخدير عصب أو ضفيرة أعصاب، ولتخدير الحلق والمجاري التنفّسية قبل المناظير وإدخال الأنابيب. وتُستعمل لصقاته لتسكين الألم العصبي الحارق الذي يبقى بعد الحزام الناري، وبعض لصقاته لآلام العضلات الخفيفة في الكتف والذراع والرقبة والساق. وفي القلب يُعطى في الوريد لتسرّع القلب البطيني، ويُنظر فيه عند توقّف القلب بالرجفان البطيني. ويُستعمل خارج النشرة بتسريب وريدي ضمن خطط تسكين ما بعد العمليات، وداخل المثانة لالتهابها الخلالي.',
    en: 'It is used to numb a small area before stitching a wound or a minor surgical procedure, to numb teeth before fillings and treatment, to block a nerve or nerve plexus, and to numb the throat and airways before endoscopy and tube placement. Its patches relieve the burning nerve pain that remains after shingles, and some patches ease minor muscle aches in the shoulder, arm, neck and leg. For the heart it is given into a vein for ventricular tachycardia and considered in cardiac arrest from ventricular fibrillation. Off-label, it is given as an intravenous infusion within plans for pain relief after surgery, and into the bladder for interstitial cystitis.'
  },
  how: {
    ar: 'الإشارة العصبية تيار كهربائي تصنعه قنوات تُدخل الصوديوم إلى العصب. يدخل الليدوكايين الليف العصبي ويغلق هذه القنوات من الداخل، فتنقطع رسالة الألم قبل وصولها إلى الدماغ ويخدر المكان وحده بينما يبقى المريض واعياً. وفي القلب يعمل على القنوات نفسها في العضلة البطينية فيهدّئ الإثارة الكهربائية الشاذّة التي تسبّب التسرّع. ويفكّكه الكبد، ولهذا يتراكم عند مرضى الكبد وعند الرضّع الذين لم يكتمل نضج كبدهم، وتزيد خطورته كلما وصل إلى الدم بكمية أكبر، سواء من حقنة أو من كمية كبيرة على الجلد أو الفم أو بلعه.',
    en: 'A nerve signal is an electrical current made by channels that let sodium into the nerve. Lidocaine enters the nerve fibre and closes these channels from inside, so the pain message is cut before reaching the brain and only that area goes numb while the patient stays awake. In the heart it acts on the same channels in the ventricular muscle, calming the abnormal electrical excitation that causes the racing rhythm. The liver breaks it down, so it builds up in people with liver disease and in infants whose liver is not yet mature, and it becomes more dangerous the more reaches the blood, whether from an injection or from a large amount on the skin or in the mouth or from swallowing it.'
  },
  effects: {
    ar: 'الحقن الموضعي يسبّب عادةً لسعاً خفيفاً ثم دفئاً وخدراً، ثم وخزاً أو حرقة حين يزول الأثر، وقد تظهر كدمة صغيرة. واللصقات قد تسبّب احمراراً أو حرقة أو تورّماً في مكانها. وبعض الناس يشعرون بدوخة أو صداع أو تشوّش رؤية عابر. وبعد تخدير الحلق تتراخى ردود فعله، فلا يأكل المريض ولا يشرب حتى يعود الإحساس كي لا يغصّ. وعند إعطائه في الوريد للقلب يراقَب المريض لأن الكمية الزائدة تظهر أولاً بثقل الكلام وطنين الأذن وتنميل حول الفم والدوخة، وقد لا تظهر هذه العلامات عند المريض المخدَّر.',
    en: 'Local injection usually causes a slight sting, then warmth and numbness, then tingling or burning as it wears off, and a small bruise may appear. Patches may cause redness, burning or swelling where they are applied. Some people feel passing dizziness, headache or blurred vision. After the throat is numbed its reflexes are weakened, so the patient does not eat or drink until feeling returns, to avoid choking. When given into a vein for the heart the patient is monitored, because an excess first shows as slurred speech, ringing in the ears, tingling around the mouth and dizziness, signs that may not show in a patient under anaesthesia.'
  },
  warning: {
    ar: 'أوقف المنتج واطلب المساعدة فوراً إن ظهر تنميل حول الفم، أو طعم معدني، أو طنين، أو ثقل في الكلام، أو دوخة شديدة، أو ارتعاش، أو تشنّج، أو نبض بطيء أو غير منتظم. واطلب الطوارئ إن ظهر ازرقاق أو لون رمادي شاحب في الجلد والشفاه والأظافر مع ضيق نفس أو صداع أو تعب، أو إن ظهر شرى وتورّم في الوجه والحلق وصعوبة في البلع. ولا يُستعمل الليدوكايين اللزج ولا غيره من المخدّرات الموضعية لألم التسنين عند الرضّع والصغار، فقد سجّلت هيئة الدواء الأمريكية تشنّجات وأذى دماغياً ومشكلات قلبية ووفيات؛ والبديل تدليك اللثة بإصبع نظيف أو عضّاضة مطاطية صلبة.',
    en: 'Stop the product and get help immediately for tingling around the mouth, a metallic taste, ringing in the ears, slurred speech, severe dizziness, trembling, a seizure, or a slow or irregular pulse. Seek emergency care for blue or pale grey skin, lips and nails with breathlessness, headache or fatigue, or for hives with swelling of the face and throat and difficulty swallowing. Viscous lidocaine and other local anaesthetics must not be used for teething pain in babies and young children: the US FDA has recorded seizures, brain injury, heart problems and deaths; instead, rub the gums with a clean finger or give a firm rubber teething ring.'
  },
  interact: {
    ar: 'يرفع البروبرانولول تركيزه في الدم كثيراً، ويُحتاط معه عند من يأخذ الديجوكسين وعنده تسمّم به أو حصار في التوصيل القلبي، ومع الأدوية التي تثبّط إنزيمات الكبد مثل الفلوفوكسامين. ويزيد خطر الميتهيموغلوبينية مع النترات والدابسون والسلفا والكلوروكين والهيدروكسي يوريا والفينوباربيتال والفينيتوين، وعند من لديه فقر دم أو اعتلال في الهيموغلوبين. وتنصح نشرة اللصقة بسؤال الطبيب قبل جمعها مع الباراسيتامول. وتجتمع سمّيته مع أي مخدّر موضعي آخر يُستعمل في الوقت نفسه، فلا تجمع لصقة وكريماً ومخدّراً آخر دون سؤال.',
    en: 'Propranolol raises its blood level considerably, and caution is needed in people on digoxin who have digoxin toxicity or a heart conduction block, and with drugs that inhibit liver enzymes such as fluvoxamine. The risk of methaemoglobinaemia rises with nitrates, dapsone, sulfonamides, chloroquine, hydroxyurea, phenobarbital and phenytoin, and in people with anaemia or a haemoglobin disorder. The patch leaflet advises asking a doctor before combining it with paracetamol. Its toxicity adds to that of any other local anaesthetic used at the same time, so do not combine a patch, a cream and another numbing product without asking.'
  },
  avoid: {
    ar: 'لا يُستعمل لمن تحسّس منه أو من مخدّرات الأميد. ولا يُعطى دواءً للقلب لمن عنده حصار متقدّم في التوصيل الكهربائي للقلب دون ناظم، أو متلازمة وولف باركنسون وايت، أو نوبات آدمز ستوكس. ويُحتاط معه في أمراض الكبد، وعند الرضّع لعدم نضج كبدهم، وعند المسنّين. ولا توضع لصقاته وكريماته على جلد مجروح أو متهيّج أو قرب العين، ولا يُقرَّب منها مصدر حرارة كالوسادة الكهربائية، وتُطوى المستعملة على نفسها وتُرمى بعيداً عن الأطفال والحيوانات. وتعدّه الجمعيات المختصّة آمناً في الحمل لتخدير الأسنان والفم، ولا يمنع الرضاعة لأن ما يصل الحليب قليل.',
    en: 'It is not used by anyone allergic to it or to amide anaesthetics. It is not given as a heart drug to people with an advanced heart conduction block without a pacemaker, Wolff-Parkinson-White syndrome or Adams-Stokes attacks. Caution is needed in liver disease, in infants because of their immature liver, and in older people. Patches and creams are not applied to broken or irritated skin or near the eyes, heat sources such as heating pads are kept away from them, and used patches are folded onto themselves and thrown away out of reach of children and pets. Professional bodies consider it safe in pregnancy for dental and oral anaesthesia, and it does not prevent breastfeeding because little reaches the milk.'
  },
  updated: '2026-09-11',
  src: [
    'https://www.ncbi.nlm.nih.gov/books/NBK539881/',
    'https://www.ncbi.nlm.nih.gov/books/NBK499964/',
    'https://medlineplus.gov/druginfo/meds/a603026.html',
    'https://www.fda.gov/consumers/consumer-updates/safely-soothing-teething-pain-infants-and-children',
    'https://www.nhs.uk/tests-and-treatments/local-anaesthesia/'
  ]
};

RX_BODY['lidocaine-epinephrine'] = {
  what: {
    ar: 'هذا خليط من مخدّر موضعي هو الليدوكايين ومادة قابضة للأوعية هي الأدرينالين (الإبينفرين)، وهو أشيع ما يُحقن في عيادات الأسنان وفي كثير من الإجراءات الجراحية الصغيرة. الليدوكايين يُخدّر، والأدرينالين يضيّق الأوعية الدموية في المكان فيبقى المخدّر حيث حُقن مدّة أطول ويكفي منه مقدار أقلّ. لا يُصرف للاستعمال المنزلي؛ يحقنه طبيب الأسنان أو الطبيب في العيادة أو غرفة العمليات. وتحتوي عبواته عادةً مادة حافظة من السلفيت تحمي الأدرينالين من التلف، وهذا مهمّ لمن يتحسّس منها.',
    en: 'This is a mixture of a local anaesthetic, lidocaine, and a blood-vessel-tightening substance, adrenaline (epinephrine), and it is the most common injection in dental clinics and in many minor surgical procedures. Lidocaine numbs, and adrenaline narrows the blood vessels at the site so the anaesthetic stays where it was injected for longer and a smaller amount is enough. It is not dispensed for home use; a dentist or doctor injects it in the clinic or operating room. Its vials usually contain a sulfite preservative that protects the adrenaline from spoiling, which matters for people sensitive to sulfites.'
  },
  why: {
    ar: 'يُستعمل لإحداث تخدير موضعي أو ناحي للبالغين والأطفال في الجراحة، وفي علاج الأسنان وجراحة الفم، وفي الإجراءات التشخيصية والعلاجية، وفي بعض إجراءات الولادة. ففي الأسنان يُحقن قبل حشو التسوّس وعلاج العصب وخلع الأسنان وضروس العقل المنطمرة، ويمنح عصب السنّ تخديراً يكفي أغلب هذه الإجراءات. وفي الجراحة الصغيرة يُحقن حول موضع العمل ليبقى المريض مستيقظاً دون ألم. ويُفضَّل على الليدوكايين وحده حين يحتاج الطبيب تخديراً أطول أو مقداراً أقلّ من المخدّر يصل إلى الدم.',
    en: 'It is used to produce local or regional anaesthesia in adults and children for surgery, dental treatment and oral surgery, diagnostic and therapeutic procedures, and some obstetric procedures. In dentistry it is injected before filling decayed teeth, root canal treatment, extractions and removal of impacted wisdom teeth, and it numbs the tooth’s nerve enough for most of these procedures. In minor surgery it is injected around the work site so the patient stays awake without pain. It is preferred over lidocaine alone when the doctor needs longer numbness or less anaesthetic reaching the blood.'
  },
  how: {
    ar: 'يغلق الليدوكايين قنوات الصوديوم في الأعصاب فلا تعبر إشارة الألم إلى الدماغ، وهذا هو الخدر. لكن الدم يحمل المخدّر بعيداً عن مكانه بسرعة، فيقصر أثره وترتفع كميّته في الدورة الدموية. وهنا دور الأدرينالين: يضيّق الأوعية الصغيرة حول موضع الحقن، فيبطؤ امتصاص المخدّر إلى الدم ويبقى تركيزه في الأنسجة مدّة أطول. والنتيجة تخدير أطول بمقدار أقلّ من المخدّر. لكن هذا التضييق نفسه هو ما يوجب الحذر في الأعضاء التي يغذّيها شريان طرفي واحد، وما يجعل للأدرينالين أثراً على القلب والضغط إن وصل الدم.',
    en: 'Lidocaine closes sodium channels in the nerves so the pain signal cannot cross to the brain, and that is the numbness. But the blood quickly carries the anaesthetic away from its site, shortening its effect and raising the amount in the circulation. This is where adrenaline comes in: it narrows the small vessels around the injection, slowing absorption of the anaesthetic into the blood and keeping its concentration in the tissues for longer. The result is longer numbness with a smaller amount of anaesthetic. But that same narrowing is why care is needed in parts supplied by a single end artery, and why the adrenaline affects the heart and blood pressure if it reaches the blood.'
  },
  effects: {
    ar: 'يُتوقّع لسع لحظي عند الحقن، ثم خدر في الشفة واللسان والخدّ قد يستمرّ ساعات بعد علاج الأسنان، ثم وخز أو حرقة حين يزول. وقد يشعر المريض بتسارع في النبض بعد الحقن بقليل بسبب الأدرينالين، ويزول عادةً سريعاً. وقد تظهر كدمة أو ألم في موضع الإبرة، أو دوخة أو صداع أو تشوّش رؤية عابر. والخطر الشائع بعد علاج الأسنان ليس الدواء بل عضّ الشفة أو اللسان أو باطن الخدّ دون شعور، وهو أكثر عند الأطفال ومن لديهم احتياجات خاصة، ولهذا يُمنع مضغ الطعام الصلب حتى يعود الإحساس.',
    en: 'A brief sting is expected on injection, then numbness of the lip, tongue and cheek that may last hours after dental treatment, then tingling or burning as it fades. The patient may feel the pulse speed up shortly after the injection because of the adrenaline, which usually settles quickly. There may be a bruise or soreness at the needle site, or passing dizziness, headache or blurred vision. The common danger after dental work is not the drug but biting the lip, tongue or inside of the cheek without feeling it, more common in children and people with special needs, which is why chewing solid food is avoided until feeling returns.'
  },
  warning: {
    ar: 'لا تمضغ طعاماً صلباً ولا تعضّ شفتك أو لسانك حتى يزول الخدر، وقد يطول ساعات، وراقب الأطفال في ذلك. أخبر الطبيب فوراً أثناء الحقن إن شعرت بتنميل حول الفم، أو طعم معدني، أو طنين، أو دوخة شديدة، أو خفقان قويّ، أو ألم في الصدر. واطلب الطوارئ إن ظهر ازرقاق في الجلد أو الشفاه مع ضيق نفس، أو صفير وضيق تنفّس وشرى بعد الحقن خصوصاً عند مرضى الربو الحسّاسين للسلفيت، أو صداع شديد مفاجئ مع خفقان. وإن حُقن في إصبع أو في الأنف أو الأذن ثم بقي الجلد شاحباً بارداً أو داكناً بعد زوال الخدر، فراجع الطبيب في اليوم نفسه.',
    en: 'Do not chew solid food or bite your lip or tongue until the numbness wears off, which may take hours, and watch children closely. Tell the doctor at once during the injection if you feel tingling around the mouth, a metallic taste, ringing in the ears, severe dizziness, strong palpitations or chest pain. Seek emergency care for blue skin or lips with breathlessness, for wheezing, breathlessness and hives after the injection, especially in people with asthma who are sensitive to sulfites, or for a sudden severe headache with palpitations. If it was injected into a finger, the nose or an ear and the skin stays pale, cold or dark after the numbness fades, see a doctor the same day.'
  },
  interact: {
    ar: 'الأدرينالين مصدر أغلب تعارضاته. فتحذّر النشرة من استعماله مع مثبّطات الأكسيداز أحادي الأمين ومضادّات الاكتئاب ثلاثية الحلقات وحاصرات بيتا غير الانتقائية كالبروبرانولول والفينوثيازينات والبيوتيروفينونات، وأثناء غازات التخدير القوية أو بعدها، لخطر ارتفاع شديد في الضغط أو اضطراب في نظم القلب. ويُحتاط منه عند من يتعاطى الكوكايين. ويزيد الليدوكايين خطر الميتهيموغلوبينية مع النترات والسلفا والدابسون وغيرها من المواد المؤكسدة. أخبر طبيب الأسنان بكل أدويتك، ولا سيّما أدوية الاكتئاب والضغط والقلب، قبل أن يحقن.',
    en: 'Adrenaline is the source of most of its interactions. The label warns against using it with monoamine oxidase inhibitors, tricyclic antidepressants, non-selective beta-blockers such as propranolol, phenothiazines and butyrophenones, and during or after potent inhaled anaesthetics, because of the risk of severe high blood pressure or heart rhythm disturbance. Caution is needed in people who use cocaine. The lidocaine raises the risk of methaemoglobinaemia with nitrates, sulfonamides, dapsone and other oxidising agents. Tell your dentist about all your medicines, especially those for depression, blood pressure and the heart, before the injection.'
  },
  avoid: {
    ar: 'لا يُعطى لمن تحسّس من الليدوكايين أو من مخدّرات الأميد، ويُتجنّب عند الحسّاسية من السلفيت الذي في العبوة، ويحتاط منه مرضى الربو خصوصاً. ويحتاط معه مرضى القلب الإكليلي واضطرابات النظم وارتفاع الضغط وفرط نشاط الدرقية غير المسيطر عليه، لأن الأدرينالين قد يطلق عندهم نوبة ضغط أو احتشاءً أو اضطراب نظم، فأخبر طبيبك أو طبيب أسنانك بها قبل الحقن. وتوصي النشرة بتقييد كميته بشدّة في الأعضاء التي يغذّيها شريان طرفي: أصابع اليدين والقدمين والأنف والأذن والقضيب. ويُستعمل للبالغين والأطفال وفي الولادة بتقدير الطبيب، ويُعدّ الليدوكايين آمناً لتخدير الأسنان في الحمل.',
    en: 'It is not given to anyone allergic to lidocaine or amide anaesthetics, is avoided in people sensitive to the sulfite in the vial, and people with asthma in particular need caution. People with coronary heart disease, rhythm disorders, high blood pressure or uncontrolled overactive thyroid need caution, because the adrenaline may trigger a blood pressure crisis, heart attack or rhythm disturbance in them, so tell your doctor or dentist beforehand. The label advises strictly limiting the amount in parts supplied by end arteries: fingers, toes, nose, ears and penis. It is used in adults, children and obstetrics at the doctor’s judgement, and lidocaine is considered safe for dental anaesthesia in pregnancy.'
  },
  updated: '2026-09-11',
  src: [
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2c58deba-dbb2-4e73-a173-36053536f03e',
    'https://www.ncbi.nlm.nih.gov/books/NBK610935/',
    'https://www.ncbi.nlm.nih.gov/books/NBK539881/',
    'https://www.nhs.uk/tests-and-treatments/local-anaesthesia/'
  ]
};

RX_BODY['ephedrine'] = {
  what: {
    ar: 'الإيفيدرين دواء منبّه للجهاز العصبي الودّي، أي من الأدوية التي تحاكي أثر الأدرينالين في الجسم فترفع الضغط وتسرّع القلب وتوسّع الشعب الهوائية. يُستعمل اليوم أساساً حقنةً في الوريد داخل غرف العمليات لرفع ضغط الدم حين يهبط بسبب التخدير. وكانت له قديماً استعمالات واسعة في الربو واحتقان الأنف، وبقيت منه تركيبات فموية قليلة لأعراض الربو الخفيفة، ودخل مكمّلات التنحيف في مطلع هذا القرن ثم تراجع بعد أن رُبط بأذى خطير على القلب والنفس. ومصدره الأصلي نبتة الإيفيدرا.',
    en: 'Ephedrine is a sympathetic nervous system stimulant, one of the drugs that mimic adrenaline in the body, raising blood pressure, speeding the heart and widening the airways. Today it is used mainly as an injection into a vein in operating rooms to raise blood pressure when anaesthesia makes it fall. It once had wide use for asthma and nasal congestion, a few oral combinations remain for mild asthma symptoms, and it entered weight-loss supplements early this century before declining after being linked to serious heart and psychiatric harm. Its original source is the ephedra plant.'
  },
  why: {
    ar: 'الداعي الرئيسي المعتمد هو هبوط الضغط المهمّ أثناء التخدير، إذ يوسّع التخدير العام الأوعية فيهبط الضغط ويحتاج الفريق إلى رافع له. وهو كثيراً ما يكون الخيار الأول لهبوط الضغط الذي يسبّبه التخدير النصفي أو الإيبيدورال، خصوصاً في العمليات القيصرية لأنه يحافظ على تدفّق الدم إلى الرحم أفضل من بعض البدائل، ولأنه لا يبطئ النبض كما تفعل رافعات ضغط أخرى. أما الربو فحلّت محلّه موسّعات شعب انتقائية أكثر أماناً للقلب مثل السالبوتامول. ويُستعمل خارج النشرة أحياناً في الوهن العضلي الوبيل وعند تضيّق الشعب لدى من يأخذ حاصرات بيتا.',
    en: 'The main approved reason is clinically important low blood pressure during anaesthesia: general anaesthesia widens the blood vessels, pressure falls and the team needs something to raise it. It is often the first choice for the low blood pressure caused by spinal or epidural anaesthesia, especially in caesarean sections, because it preserves blood flow to the womb better than some alternatives and does not slow the pulse as other pressure-raising drugs do. For asthma it has been replaced by selective airway openers that are safer for the heart, such as salbutamol. It is sometimes used off-label in myasthenia gravis and for airway narrowing in people taking beta-blockers.'
  },
  how: {
    ar: 'يعمل الإيفيدرين بطريقتين: يلامس بنفسه مستقبلات الأدرينالين، ويدفع نهايات الأعصاب إلى إطلاق مخزونها من النورأدرينالين ويمنع إعادة امتصاصه، وهذه الطريقة غير المباشرة هي الأساس. والنتيجة انقباض الأوعية فيرتفع الضغط، وقوّة أكبر في انقباض القلب مع نبض محفوظ أو أسرع، وتوسّع في الشعب الهوائية. ولأنه يعتمد على مخزون الأعصاب فإن تكرار إعطائه يستنزف هذا المخزون فيضعف أثره تدريجياً، وهي ظاهرة تُسمّى «التسامح السريع»، ولهذا يُعطى دفعات لا تسريباً مستمراً. وتختلف استجابة الناس له بحسب تكوينهم الوراثي.',
    en: 'Ephedrine works in two ways: it acts directly on adrenaline receptors, and it pushes nerve endings to release their store of noradrenaline while blocking its reuptake, and this indirect route is the main one. The result is narrowed blood vessels, so pressure rises, a stronger heartbeat with a maintained or faster pulse, and wider airways. Because it relies on the nerves’ stores, repeated doses deplete them and its effect gradually weakens, a phenomenon called “tachyphylaxis”, which is why it is given in boluses rather than as a continuous infusion. People’s response to it varies with their genetic makeup.'
  },
  effects: {
    ar: 'عند المريض المستيقظ قد يسبّب خفقاناً وصداعاً ودوخة وغثياناً وقيئاً وتململاً وقلقاً. ويرتفع الضغط والنبض، وهذا هو المطلوب منه، لكنه قد يزيد عن الحاجة. ويستطيع إطلاق اضطرابات في نظم القلب خصوصاً عند من لديه استعداد لها أو يأخذ الديجوكسين. ومع الأرق والتوتّر قد يصعب التبوّل عند كبار السنّ ومن عندهم تضخّم البروستاتا. أما الاستعمال الطويل أو المفرط، كما في مكمّلات التنحيف والطاقة، فرُبط باضطرابات بطينية خطيرة ومشكلات نفسية، وبأذى في عضلة القلب، وبحصى في المسالك البولية.',
    en: 'In an awake patient it may cause palpitations, headache, dizziness, nausea, vomiting, restlessness and anxiety. Blood pressure and pulse rise, which is what it is wanted for, but they may rise more than needed. It can trigger heart rhythm disturbances, especially in people prone to them or taking digoxin. Along with sleeplessness and nervousness, passing urine may become difficult in older people and those with an enlarged prostate. Long-term or excessive use, as in weight-loss and energy supplements, has been linked to dangerous ventricular rhythm disturbances, psychiatric problems, damage to the heart muscle and urinary stones.'
  },
  warning: {
    ar: 'يُعطى في المستشفى تحت مراقبة الضغط والنبض، فأخبر الفريق فوراً إن شعرت بخفقان شديد أو ألم في الصدر أو صداع حادّ أو ضيق نفس. ومن يأخذ منتجاً فيه إيفيدرين أو نبتة الإيفيدرا خارج المستشفى، كأقراص للربو أو مكمّل للطاقة أو التنحيف، فليتوقّف ويطلب الطوارئ عند ألم أو ضغط في الصدر، أو خفقان سريع أو غير منتظم، أو صداع مفاجئ شديد، أو إغماء، أو هياج وأفكار غريبة وشكّ في الآخرين. ويتوقّف ويراجع الطبيب إن ظهر أرق شديد أو قلق مستمرّ أو عسر في التبوّل أو ألم في الخاصرة. والجهات الطبية لم تعد تنصح به للتنحيف.',
    en: 'It is given in hospital under blood pressure and pulse monitoring, so tell the team at once if you feel strong palpitations, chest pain, a severe headache or breathlessness. Anyone taking a product containing ephedrine or the ephedra plant outside hospital, such as asthma tablets or an energy or weight-loss supplement, should stop and seek emergency care for chest pain or pressure, a fast or irregular heartbeat, a sudden severe headache, fainting, or agitation, strange thoughts and suspicion of others. Stop and see a doctor for severe insomnia, persistent anxiety, difficulty passing urine or pain in the flank. Medical bodies no longer recommend it for weight loss.'
  },
  interact: {
    ar: 'أخطر تعارضاته مع مثبّطات الأكسيداز أحادي الأمين، إذ تعدّ المراجع استعماله أثناءها أو خلال أسبوعين من إيقافها ممنوعاً لخطر نوبة ارتفاع ضغط حادّة. وتحذّر النشرة الرسمية من جمعه مع الأدوية القابضة للرحم مثل الميثيل إرغونوفين بعد الولادة، لخطر ارتفاع شديد في الضغط قد يصل إلى السكتة الدماغية. ويزيد الكلونيدين والأوكسيتوسين والبروبوفول والأتروبين أثره في رفع الضغط، بينما تضعفه حاصرات ألفا وبيتا والريسيربين والكينيدين. ومع الثيوفيلين يزيد الغثيان والتوتّر والأرق، ومع الديجوكسين وسائر غليكوزيدات القلب يزيد خطر اضطراب النظم. ويتضاعف أثره المنبّه مع الكافيين، وهو ما جعل خلطات التنحيف خطرة.',
    en: 'Its most dangerous interaction is with monoamine oxidase inhibitors: references regard its use while taking them or within two weeks of stopping them as forbidden because of the risk of an acute blood pressure crisis. The official label warns against combining it with womb-contracting drugs such as methylergonovine after childbirth, because of the risk of severe high blood pressure that may go as far as a stroke. Clonidine, oxytocin, propofol and atropine increase its pressure-raising effect, while alpha- and beta-blockers, reserpine and quinidine weaken it. With theophylline it increases nausea, nervousness and insomnia, and with digoxin and other cardiac glycosides it raises the risk of rhythm disturbance. Its stimulant effect adds to caffeine, which is what made weight-loss mixtures dangerous.'
  },
  avoid: {
    ar: 'لا تذكر النشرة الأمريكية للحقنة موانع مطلقة، لكن المراجع الطبية تحذّر من استعماله عند ارتفاع الضغط الحادّ أو تسرّع القلب، وفي مرض القلب الإقفاري لأنه يزيد حاجة القلب إلى الأكسجين، وفي قصور القلب وتضيّق الصمام الأبهري الذي يسوء فيه تسرّع القلب، وعند احتباس البول وتضخّم البروستاتا، ومع مثبّطات الأكسيداز أحادي الأمين. وفي الحمل بياناته محدودة وإن كان شائعاً في العمليات القيصرية، وسُجّلت حموضة في دم بعض المواليد. ولا يُنصح به للمرضع لغياب بيانات عن أثره في الرضيع، ولم تثبت سلامته وفعاليته عند الأطفال، ويراقَب المسنّون ومرضى الكلى عن قرب.',
    en: 'The US label for the injection lists no absolute contraindications, but medical references caution against its use in acute high blood pressure or a racing heart, in ischaemic heart disease because it raises the heart’s oxygen demand, in heart failure and in aortic valve stenosis where a fast heart rate is harmful, in urinary retention and enlarged prostate, and with monoamine oxidase inhibitors. In pregnancy its data are limited, although it is common in caesarean sections, and acidosis has been recorded in the blood of some newborns. It is not recommended for breastfeeding women because there are no data on its effect on the baby, its safety and effectiveness in children are not established, and older people and those with kidney disease are monitored closely.'
  },
  updated: '2026-09-11',
  src: [
    'https://www.ncbi.nlm.nih.gov/books/NBK547661/',
    'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=78c1daef-6e1e-5f2c-e053-2a91aa0a0dba'
  ]
};

RX_BODY['atropine'] = {
  what: {
    ar: 'الأتروبين دواء قديم من فصيلة مضادّات الكولين، أو «مضادّات المسكارين»، يُعطى حقناً في المستشفيات والإسعاف، ويأتي قطرةً ومرهماً للعين. وهو من أدوية الإنعاش الأساسية: يسرّع القلب البطيء، ويُعدّ الترياق الأول للتسمّم بالمبيدات الحشرية الفسفورية العضوية وغازات الأعصاب. وأثره عكس أثر الجهاز العصبي «نظير الودّي» الذي يبطئ القلب ويزيد اللعاب وإفرازات الشعب ويضيّق الحدقة ويحرّك الأمعاء والمثانة. ولأنه قويّ فإن كمية صغيرة منه قد تكون خطرة على طفل صغير إن ابتلعها.',
    en: 'Atropine is an old drug of the anticholinergic, or “antimuscarinic”, class, given by injection in hospitals and emergency care, and available as eye drops and ointment. It is a core resuscitation drug: it speeds a slow heart and is the first antidote for poisoning by organophosphate insecticides and nerve agents. Its effect is the opposite of the “parasympathetic” nervous system, which slows the heart, increases saliva and airway secretions, narrows the pupil and moves the bowel and bladder. Because it is potent, a small amount can be dangerous to a young child who swallows it.'
  },
  why: {
    ar: 'يُعطى في الوريد لبطء القلب المصحوب بأعراض كالدوخة والإغماء وهبوط الضغط، ويُعطى بمقادير كبيرة ومتكرّرة في التسمّم بالمبيدات الفسفورية وغازات الأعصاب حين تغرق الرئتان بالإفرازات ويبطؤ القلب. وقد يُستعمل لتجفيف الإفرازات أثناء التخدير، ومع النيوستيغمين لمنع بطء القلب عند عكس أثر مرخيات العضلات، وقبل إدخال أنبوب التنفّس عند الأطفال. أما قطرته فتوسّع الحدقة وترخي عضلة التركيز لفحص النظر، وتخفّف ألم التهاب العين الداخلي، وتُستعمل لعلاج كسل العين عند الأطفال، وبتركيز منخفض مع اللعب في الهواء الطلق لإبطاء تفاقم قصر النظر عندهم.',
    en: 'It is given into a vein for a slow heart with symptoms such as dizziness, fainting and low blood pressure, and in large, repeated amounts for organophosphate and nerve agent poisoning when the lungs flood with secretions and the heart slows. It may be used to dry secretions during anaesthesia, with neostigmine to prevent a slow heart when reversing muscle relaxants, and before placing a breathing tube in children. Its eye drops widen the pupil and relax the focusing muscle for sight testing, ease the pain of inflammation inside the eye, treat lazy eye in children, and at low strength, together with outdoor play, slow the worsening of short-sightedness in children.'
  },
  how: {
    ar: 'ينقل الجهاز نظير الودّي أوامره بمادة اسمها الأسيتيل كولين تلتصق بمستقبلات تُسمّى «المسكارينية» في القلب والغدد والعين والأمعاء والمثانة، فتبطئ القلب وتزيد الإفرازات وتضيّق الحدقة. يجلس الأتروبين على هذه المستقبلات وينافس الأسيتيل كولين عليها دون أن ينشّطها، فيرفع «كابح» العصب الحائر عن القلب فيتسارع، وتجفّ الإفرازات، وتتّسع الحدقة وترتخي عضلة التركيز فيتشوّش النظر القريب. وفي التسمّم بالمبيدات يتراكم الأسيتيل كولين لأن المبيد يعطّل الإنزيم الذي يفكّكه، فيأتي الأتروبين ليحجب أثره على هذه المستقبلات. ولا يعمل على القلب المزروع لأن العصب الحائر مقطوع عنه.',
    en: 'The parasympathetic system sends its commands through a substance called acetylcholine, which binds to “muscarinic” receptors in the heart, glands, eyes, bowel and bladder, slowing the heart, increasing secretions and narrowing the pupil. Atropine sits on these receptors and competes with acetylcholine for them without activating them, releasing the vagus nerve’s “brake” on the heart so it speeds up, drying secretions, widening the pupil and relaxing the focusing muscle so near vision blurs. In pesticide poisoning acetylcholine builds up because the pesticide disables the enzyme that breaks it down, and atropine blocks its effect on these receptors. It does not work on a transplanted heart because the vagus nerve to it has been cut.'
  },
  effects: {
    ar: 'آثاره الشائعة امتداد لطريقة عمله: جفاف الفم، وتشوّش الرؤية والحساسية للضوء، وتسارع القلب، واحمرار الوجه وسخونة الجلد، وقلّة التعرّق وخصوصاً عند كبار السنّ، والإمساك، وصعوبة التبوّل. أما القطرة فقد تسبّب تهيّجاً في العين وتورّماً في الجفن وتشوّشاً في الرؤية وحساسية للضوء قد يطول أثرها، وقد يُمتصّ منها ما يكفي لجفاف الفم واحمرار الوجه عند الأطفال. وكبار السنّ أكثر عرضة للارتباك والهذيان واحتباس البول والإمساك منه، ولهذا تنصح معايير الأدوية للمسنّين بتجنّبه في غير العين.',
    en: 'Its common effects follow from how it works: dry mouth, blurred vision and light sensitivity, a fast heart, a flushed face and hot skin, reduced sweating especially in older people, constipation and difficulty passing urine. The eye drops may cause eye irritation, swollen eyelids, blurred vision and light sensitivity that may last a long time, and enough may be absorbed to cause a dry mouth and flushing in children. Older people are more prone to confusion, delirium, urinary retention and constipation from it, which is why prescribing criteria for older adults advise avoiding it except in the eye.'
  },
  warning: {
    ar: 'اطلب الطوارئ فوراً إن ظهرت بعد الحقنة أو القطرة أو ابتلاعها صورة التسمّم بمضادّات الكولين: حدقتان متّسعتان، وجلد حارّ جافّ محمرّ، وحمّى، ونبض سريع أو غير منتظم، وارتباك أو هياج أو هلاوس، وتمايل في المشي، وعجز عن التبوّل؛ ولهذا التسمّم ترياق يعطيه الطبيب. ومن استعمل القطرة وعنده زرق ضيّق الزاوية قد تنطلق عنده نوبة انغلاق حادّة، فأيّ ألم مفاجئ في العين بعدها يستوجب الطوارئ. وبعد القطرة اضغط على الزاوية الداخلية للعين وامسح الزائد لتقليل ما يُمتصّ، ولا تقد السيارة حتى تتّضح رؤيتك، واحفظ العبوة بعيداً عن الأطفال.',
    en: 'Seek emergency care at once if, after an injection, eye drops or swallowing it, the picture of anticholinergic poisoning appears: widely dilated pupils, hot, dry, flushed skin, fever, a fast or irregular pulse, confusion, agitation or hallucinations, unsteady walking and inability to pass urine; there is an antidote a doctor can give. In anyone with narrow-angle glaucoma the drops may trigger an acute angle-closure attack, so any sudden eye pain afterwards needs emergency care. After the drops, press on the inner corner of the eye and wipe off the excess to reduce absorption, do not drive until your vision is clear, and keep the bottle away from children.'
  },
  interact: {
    ar: 'يتضاعف أثره المضاد للكولين مع كل دواء يحمل الصفة نفسها: مضادّات الهيستامين القديمة، ومضادّات الذهان، ومضادّات الاكتئاب ثلاثية الحلقات، وأدوية فرط نشاط المثانة، ومضادّات تشنّج الأمعاء، وبعض مرخيات العضلات، والغليكوبيرولات، فيزيد جفاف الفم والإمساك واحتباس البول والارتباك وخصوصاً عند المسنّين. وتنبّه نشرة القطرة إلى أن أدوية الحساسية والزكام التي تُشترى بلا وصفة قد تتداخل معها. ويزيد الإمساك مع الإيلوكسادولين، ويقلّل امتصاص الميكسيليتين. أخبر الطبيب بكل أدويتك قبل استعماله.',
    en: 'Its anticholinergic effect adds up with every drug of the same kind: older antihistamines, antipsychotics, tricyclic antidepressants, overactive bladder medicines, bowel antispasmodics, some muscle relaxants and glycopyrrolate, increasing dry mouth, constipation, urinary retention and confusion, especially in older people. The eye drop leaflet notes that allergy and cold medicines bought without prescription may interact with it. It worsens constipation with eluxadoline and reduces the absorption of mexiletine. Tell your doctor about all your medicines before using it.'
  },
  avoid: {
    ar: 'يُحتاط منه، إلا حين تفرض الحالة الإسعافية غير ذلك، عند من عنده زرق ضيّق الزاوية، أو انسداد في مجرى البول أو تضخّم يعيقه، أو شلل في الأمعاء أو تضخّم القولون السمّي أو تضيّق مخرج المعدة، أو الوهن العضلي الوبيل، أو مرض الشرايين التاجية أو احتشاء حديث أو قصور القلب أو تسرّع النظم، أو مرض رئوي مزمن تتكثّف فيه الإفرازات. ويُتجنّب روتينياً عند كبار السنّ. وفي الحمل يعبر المشيمة وقد يسرّع قلب الجنين دون تشوّهات معروفة، ولا يُمنع حين تستدعيه الحاجة. والجرعة المفردة لا تؤثّر في الرضاعة، أما الاستعمال المتكرّر فقد يقلّل الحليب.',
    en: 'Caution is needed, unless an emergency dictates otherwise, in narrow-angle glaucoma, blocked or obstructed urine flow, paralysed bowel, toxic megacolon or narrowed stomach outlet, myasthenia gravis, coronary artery disease, a recent heart attack, heart failure or a racing rhythm, and chronic lung disease with thick secretions. It is avoided routinely in older people. In pregnancy it crosses the placenta and may speed the baby’s heart without known malformations, and it is not withheld when needed. A single dose does not affect breastfeeding, but repeated use may reduce milk supply.'
  },
  updated: '2026-09-11',
  src: [
    'https://www.ncbi.nlm.nih.gov/books/NBK470551/',
    'https://www.medlineplus.gov/druginfo/meds/a682487.html',
    'https://www.ncbi.nlm.nih.gov/books/NBK499995/'
  ]
};

RX_BODY['atracurium'] = {
  what: {
    ar: 'الأتراكوريوم مُرخٍ لعضلات الهيكل من فئة «حاصرات الوصل العصبي العضلي غير المُزيلة للاستقطاب»، يُحقن في الوريد في غرف العمليات والعناية المركّزة فقط. يشلّ العضلات الإرادية مؤقتاً بما فيها عضلات التنفّس، فلا يُعطى إلا لمريض تحت التخدير أو التهدئة ومعه جهاز أو فريق يتنفّس عنه. مدّة أثره متوسّطة، ويمتاز بطريقة تفكّك فريدة: يتحلّل في الدم تلقائياً بحرارة الجسم وحموضته وبإنزيمات الدم، فلا يعتمد على الكبد ولا الكلى. وليس له أي أثر منوّم أو مسكّن للألم.',
    en: 'Atracurium is a skeletal muscle relaxant of the “non-depolarising neuromuscular blocker” class, injected into a vein only in operating rooms and intensive care. It temporarily paralyses voluntary muscles, including the breathing muscles, so it is given only to a patient under anaesthesia or sedation with a machine or team breathing for them. Its action is of intermediate length, and it has a unique way of breaking down: it falls apart in the blood by itself according to body temperature and acidity, and through blood enzymes, so it does not depend on the liver or kidneys. It has no sleep-inducing or pain-relieving effect at all.'
  },
  why: {
    ar: 'يُستعمل لتسهيل إدخال أنبوب التنفّس في القصبة الهوائية، ولإرخاء العضلات أثناء العمليات تحت التخدير العام كي يعمل الجرّاح دون أن تنقبض عضلات المريض، ولإرخاء العضلات عند المرضى على أجهزة التنفّس في العناية المركّزة. ومن استعمالاته خارج النشرة إطالة الإرخاء في جراحات المنظار، والمساعدة في ضبط ضغط الدماغ بعد إصاباته، وفي ضيق التنفّس الحادّ الشديد على جهاز التنفّس. ويُفضَّل عند مرضى الكلى المزمنة لأن تخلّص الجسم منه لا يمرّ بالكلى.',
    en: 'It is used to make it easier to place a breathing tube in the windpipe, to relax muscles during operations under general anaesthesia so the surgeon can work without the patient’s muscles tensing, and to relax muscles in patients on breathing machines in intensive care. Off-label uses include prolonging relaxation during laparoscopic surgery, helping control pressure in the brain after head injury, and severe acute respiratory distress on a ventilator. It is preferred in people with chronic kidney disease because the body clears it without going through the kidneys.'
  },
  how: {
    ar: 'حين يأمر العصب العضلة بالانقباض يطلق عند نهايته مادة الأسيتيل كولين، فتلتصق بمستقبلات «نيكوتينية» على سطح العضلة فتنقبض. يجلس الأتراكوريوم على هذه المستقبلات وينافس الأسيتيل كولين عليها دون أن ينشّطها، فتصل الأوامر ولا تستجيب العضلة. والأثر قابل للعكس: حين ينخفض تركيزه، أو يُعطى دواء كالنيوستيغمين يزيد الأسيتيل كولين، تعود القوّة. ويتفكّك بطريقتين لا تحتاجان الكبد ولا الكلى، لكن البرودة وحموضة الدم تبطئانه. ومن نواتج تفكّكه مادة تنبّه الدماغ قد تتراكم مع التسريب الطويل في العناية.',
    en: 'When a nerve tells a muscle to contract, it releases acetylcholine at its ending, which binds to “nicotinic” receptors on the muscle surface so it contracts. Atracurium sits on these receptors and competes with acetylcholine for them without activating them, so the command arrives but the muscle does not respond. The effect is reversible: when its level falls, or a drug like neostigmine that increases acetylcholine is given, strength returns. It breaks down in two ways that need neither liver nor kidneys, though cold and acidic blood slow it. One of its breakdown products stimulates the brain and may build up during long infusions in intensive care.'
  },
  effects: {
    ar: 'أشيع آثاره احمرار الجلد وتورّده، لأنه يطلق الهيستامين، وقد يرافق ذلك هبوط في الضغط وتسارع في النبض وتشنّج في الشعب أو الحنجرة، ولهذا يُعطى ببطء وبحذر لمرضى الربو والقلب. وبعد العملية قد يبقى أثر متبقٍّ من الإرخاء فيظهر ضعف أو صعوبة في التنفّس العميق أو البلع أو رؤية مزدوجة، ويراقبه الفريق في غرفة الإفاقة. ويشيع بعد التخدير العام ألم الحلق من الأنبوب والنعاس. ومع الاستعمال الطويل في العناية قد يحدث ضعف عضلي مكتسب، ونادراً تشنّجات من ناتج تفكّكه.',
    en: 'Its most common effect is redness and flushing of the skin because it releases histamine, and this may come with a fall in blood pressure, a faster pulse and spasm of the airways or larynx, which is why it is given slowly and cautiously to people with asthma and heart disease. After the operation some relaxation may linger, showing as weakness, difficulty breathing deeply or swallowing, or double vision, which the team monitors in the recovery room. A sore throat from the tube and drowsiness are common after general anaesthesia. With long use in intensive care, acquired muscle weakness may develop, and rarely seizures from its breakdown product.'
  },
  warning: {
    ar: 'هذا الدواء يشلّ ولا ينوّم، فلا يُعطى إلا مع تخدير أو تهدئة كافية. إن تذكّرت بعد العملية أنك كنت واعياً عاجزاً عن الحركة أثناءها فأخبر الفريق، فهذا أمر مهمّ يجب أن يُسجَّل. وبعد الإفاقة أخبر الممرّضة فوراً إن شعرت بضعف لا يتحسّن، أو عجز عن أخذ نفس عميق، أو صعوبة في البلع أو غصّة باللعاب، أو رؤية مزدوجة. وأثناء التخدير يراقب الفريق علامات الحساسية الشديدة، فمرخيات العضلات من أشيع أسباب التحسّس في التخدير. ومن أصابته تفاعلات تحسّسية تحت التخدير فليحفظ اسم الدواء ويخبر به كل فريق يعالجه لاحقاً.',
    en: 'This drug paralyses but does not put you to sleep, so it is given only with enough anaesthesia or sedation. If after an operation you remember being awake and unable to move during it, tell the team, because this is important and must be recorded. After waking, tell the nurse at once if you feel weakness that does not improve, cannot take a deep breath, have difficulty swallowing or choke on saliva, or have double vision. During anaesthesia the team watches for severe allergy, because muscle relaxants are among the most common causes of allergic reactions under anaesthesia. Anyone who has had an allergic reaction under anaesthesia should keep the drug’s name and tell every team that treats them later.'
  },
  interact: {
    ar: 'تقوّي غازات التخدير المستنشقة أثره فيقلّل الفريق مقداره، وتزيده المضادّات الحيوية من فئة الأمينوغليكوزيدات والبوليميكسين فيطول الشلل. وكذلك يعزّز أثره المغنيسيوم والليثيوم وأدوية النظم مثل البروكايناميد والكينيدين. وإذا أُعطي السكسينيل كولين أولاً فيجب أن ينتهي أثره قبل إعطاء الأتراكوريوم. ولا يُخلط بمحلول رينغر اللاكتاتي لأنه يسرّع تحلّله. أخبر فريق التخدير بكل أدويتك، وبخاصّة الليثيوم وأدوية نظم القلب وأي مضادّ حيوي حديث أو مغنيسيوم تأخذه.',
    en: 'Inhaled anaesthetic gases strengthen its effect so the team reduces the amount, and aminoglycoside and polymyxin antibiotics increase it so the paralysis lasts longer. Magnesium, lithium and rhythm drugs such as procainamide and quinidine also enhance it. If suxamethonium is given first, its effect must end before atracurium is given. It is not mixed with lactated Ringer’s solution because that speeds its breakdown. Tell the anaesthetic team about all your medicines, especially lithium, heart rhythm drugs and any recent antibiotic or magnesium you take.'
  },
  avoid: {
    ar: 'لا يُعطى لمن تحسّس منه أو من الكحول البنزيلي الموجود في بعض عبواته، ويُحتاط معه عند من تحسّس سابقاً من مرخّ آخر من فئته لاحتمال التحسّس المتصالب. ومرضى الوهن العضلي الوبيل ومتلازمة لامبرت إيتون شديدو الحساسية له فيراقَبون بجهاز تنبيه الأعصاب، أما مرضى الحروق فيقاومون أثره. ومرضى الربو وأمراض القلب يُعطَون إيّاه ببطء لتقليل إطلاق الهيستامين. وأخبر طبيب التخدير بأي مرض عضلي أو عصبي عندك قبل العملية. وعبوره المشيمة قليل فيقلّ ما يصل الجنين منه، ولا يوضّح مصدره الرسمي أثره في الرضاعة.',
    en: 'It is not given to anyone allergic to it or to the benzyl alcohol in some vials, and caution is needed in people previously allergic to another relaxant of its class because of possible cross-reactivity. People with myasthenia gravis and Lambert-Eaton syndrome are highly sensitive to it and are monitored with a nerve stimulator, whereas people with burns resist its effect. People with asthma and heart disease receive it slowly to reduce histamine release. Tell the anaesthetist about any muscle or nerve disease you have before the operation. Little crosses the placenta, so the baby receives little of it, and its official source does not address breastfeeding.'
  },
  updated: '2026-09-11',
  src: [
    'https://www.ncbi.nlm.nih.gov/books/NBK499995/',
    'https://www.ncbi.nlm.nih.gov/books/NBK537168/',
    'https://www.nhs.uk/tests-and-treatments/general-anaesthesia/'
  ]
};

RX_BODY['suxamethonium'] = {
  what: {
    ar: 'السكسينيل كولين، ويُسمّى أيضاً السوكساميثونيوم، أسرع مرخيات العضلات بدءاً وأقصرها أثراً: يشلّ عضلات الجسم كلها خلال أقلّ من دقيقة ويزول أثره خلال دقائق قليلة، لأن إنزيماً في الدم اسمه «الكولينستراز الكاذب» يفكّكه بسرعة. وهو المستعمل الوحيد في الممارسة من فئة المرخيات «المُزيلة للاستقطاب». يُحقن في الوريد داخل المستشفى فقط، مع مخدّر أو منوّم، ومع جاهزية كاملة للتنفّس الاصطناعي. سرعته تجعله دواء الطوارئ لإدخال أنبوب التنفّس فوراً، وأخطاره الوراثية تجعل سؤال العائلة قبله مهمّاً.',
    en: 'Suxamethonium, also called succinylcholine, is the fastest-acting and shortest-lasting muscle relaxant: it paralyses all body muscles in less than a minute and wears off within a few minutes, because an enzyme in the blood called “pseudocholinesterase” breaks it down quickly. It is the only relaxant of the “depolarising” class in practical use. It is injected into a vein only in hospital, with an anaesthetic or sedative, and with full readiness for artificial breathing. Its speed makes it the emergency drug for placing a breathing tube at once, and its inherited risks make asking about family history beforehand important.'
  },
  why: {
    ar: 'يُستعمل لإدخال أنبوب التنفّس بسرعة، كما في الطوارئ حين لا يحتمل المريض الانتظار، ولإرخاء العضلات في العمليات القصيرة، وللمساعدة في التنفّس الاصطناعي. ومن استعمالاته خارج النشرة منع التقلّصات العضلية العنيفة أثناء العلاج بالتخليج الكهربائي في الطبّ النفسي، فيحمي المريض من الإصابات أثناء الجلسة. أما عند الأطفال فتحصره النشرة الرسمية في الطوارئ فقط، بسبب خطر نادر لكنه قاتل عند من لديهم مرض عضلي لم يُشخَّص بعد. وقد يُعطى الأتروبين قبله عند الأطفال لمنع بطء القلب.',
    en: 'It is used to place a breathing tube quickly, as in emergencies when the patient cannot wait, to relax muscles in short operations and to assist artificial ventilation. An off-label use is preventing violent muscle contractions during electroconvulsive therapy in psychiatry, protecting the patient from injury during the session. In children the official label restricts it to emergencies only, because of a rare but fatal risk in those with an undiagnosed muscle disease. Atropine may be given before it in children to prevent a slow heart.'
  },
  how: {
    ar: 'يشبه السكسينيل كولين في تركيبه مادة الأسيتيل كولين التي يأمر بها العصب العضلة بالانقباض. فيلتصق بمستقبلاتها على العضلة وينشّطها، فتظهر أولاً ارتعاشات عضلية سريعة منتشرة في الجسم، لكنه لا يغادر المستقبل كما يغادره الأسيتيل كولين، فيبقى غشاء العضلة في حالة تنبّه دائم لا تسمح بانقباض جديد، فتسترخي العضلات كلها. ثم يفكّكه إنزيم الكولينستراز الكاذب في الدم فتعود القوّة خلال دقائق. فإذا نقص هذا الإنزيم، وراثياً أو بسبب الحمل أو أمراض الكبد والكلى أو سوء التغذية أو الحروق، طال الشلل ساعات.',
    en: 'Suxamethonium resembles acetylcholine, the substance a nerve uses to tell a muscle to contract. It binds to the muscle’s receptors and activates them, so rapid muscle twitches first ripple across the body, but it does not leave the receptor as acetylcholine does, so the muscle membrane stays in a constant state of excitation that allows no new contraction, and all the muscles go slack. Then pseudocholinesterase in the blood breaks it down and strength returns within minutes. If this enzyme is lacking, whether inherited or due to pregnancy, liver or kidney disease, malnutrition or burns, the paralysis lasts for hours.'
  },
  effects: {
    ar: 'تظهر في بدايته ارتعاشات عضلية واضحة، ويشيع بعد العملية ألم في العضلات يشبه ألم التمرين، وهو مزعج لكنه غير خطير. ويرفع البوتاسيوم في الدم قليلاً، وهذا لا يهمّ إلا عند من لديه استعداد لارتفاعه. وقد يبطئ القلب خصوصاً عند الأطفال، ويرفع ضغط العين والمعدة مؤقتاً. وقد تتشنّج عضلات الفكّ فتنطبق الفكّان، وهذا قد يكون أول إنذار بالحرارة الخبيثة. وعند نقص إنزيم الكولينستراز يطول الشلل فيبقى المريض على جهاز التنفّس حتى يزول الدواء، وقد يحدث تحسّس شديد نادراً.',
    en: 'Visible muscle twitches appear at the start, and muscle pain like post-exercise soreness is common after the operation, uncomfortable but not dangerous. It raises blood potassium slightly, which matters only in people prone to high potassium. It may slow the heart, especially in children, and raises pressure in the eye and stomach for a while. The jaw muscles may go into spasm and clamp shut, which can be the first warning of malignant hyperthermia. When pseudocholinesterase is lacking the paralysis lasts longer and the patient stays on the breathing machine until the drug clears, and severe allergy occurs rarely.'
  },
  warning: {
    ar: 'قبل أي تخدير أخبر الطبيب إن كان أحد أقاربك قد أصيب تحت التخدير بحرارة مرتفعة وتيبّس في العضلات، أو بقي مشلولاً على جهاز التنفّس أطول من المتوقّع، أو كان عندك أو عند طفلك مرض عضلي، أو إصابة حديثة بحروق أو سحق أو سكتة أو إصابة في النخاع أو رقاد طويل. والحرارة الخبيثة تظهر بارتفاع سريع في الحرارة وتيبّس العضلات وتسارع القلب والتنفّس وبول داكن، ويعالجها الفريق فوراً بالدانترولين. ومن أصيب بها أو ثبت عنده نقص الإنزيم فليحمل بطاقة أو سواراً طبياً، وليُفحص أقاربه من الدرجة الأولى.',
    en: 'Before any anaesthetic, tell the doctor if a relative developed a high temperature and muscle rigidity under anaesthesia or stayed paralysed on a breathing machine longer than expected, if you or your child have a muscle disease, or if you have had a recent burn, crush injury, stroke, spinal cord injury or long bed rest. Malignant hyperthermia shows as a rapid rise in temperature, muscle rigidity, a fast heart and breathing, and dark urine, and the team treats it at once with dantrolene. Anyone who has had it or has a proven enzyme deficiency should carry a medical alert card or bracelet, and their first-degree relatives should be tested.'
  },
  interact: {
    ar: 'تقوّي المضادّات الحيوية من فئة الأمينوغليكوزيدات أثره وتطيل الشلل، وكذلك مثبّطات الكولينستراز التي تمنع الإنزيم الذي يفكّكه، ومنها بعض أدوية الوهن العضلي. ويعزّز أثره أيضاً الكينيدين والبروكايناميد والليدوكايين والليثيوم والمغنيسيوم. واجتماعه مع غازات التخدير المهلجنة هو المطلق المعروف للحرارة الخبيثة عند من لديه استعداد وراثي. وإذا أُعطي قبل مرخّ من الفئة الأخرى فيجب أن ينتهي أثره أولاً. وبعض الأدوية تخفض إنزيم الكولينستراز فتطيل أثره، فأخبر فريق التخدير بكل أدويتك.',
    en: 'Aminoglycoside antibiotics strengthen its effect and prolong paralysis, as do cholinesterase inhibitors, which block the enzyme that breaks it down, including some myasthenia medicines. Quinidine, procainamide, lidocaine, lithium and magnesium also enhance it. Its combination with halogenated anaesthetic gases is the known trigger of malignant hyperthermia in people with an inherited tendency. If it is given before a relaxant of the other class, its effect must end first. Some medicines lower pseudocholinesterase and so prolong its action, so tell the anaesthetic team about all your medicines.'
  },
  avoid: {
    ar: 'يُمنع عند نقص إنزيم الكولينستراز، وبعد الحروق الواسعة والإصابات الكبيرة بعد أول يوم أو ثلاثة أيام منها، وفي الأمراض العضلية مثل حثل دوشين العضلي، وعند من لديه أو عند عائلته استعداد للحرارة الخبيثة، وعند التحسّس منه، ومع الأمينوغليكوزيدات أو مثبّطات الكولينستراز. ويُحتاط معه في الوهن العضلي والزرق ضيّق الزاوية وأمراض الكبد والكلى الشديدة، وبعد السكتة أو الرقاد الطويل. وعند الأطفال لا يُعطى إلا في الطوارئ. ولم يُربط بتشوّهات أو إجهاض، ويُستعمل في القيصرية، لكن نقص الإنزيم في الحمل قد يطيل أثره.',
    en: 'It is contraindicated in pseudocholinesterase deficiency, after extensive burns and major injuries beyond the first one to three days, in muscle diseases such as Duchenne muscular dystrophy, in people with a personal or family tendency to malignant hyperthermia, in anyone allergic to it, and with aminoglycosides or cholinesterase inhibitors. Caution is needed in myasthenia gravis, narrow-angle glaucoma, severe liver and kidney disease, and after a stroke or long bed rest. In children it is given only in emergencies. It has not been linked to birth defects or miscarriage and is used in caesarean sections, but the lower enzyme level in pregnancy may prolong its effect.'
  },
  updated: '2026-09-11',
  src: [
    'https://www.ncbi.nlm.nih.gov/books/NBK499984/',
    'https://www.ncbi.nlm.nih.gov/books/NBK430828/',
    'https://medlineplus.gov/genetics/condition/pseudocholinesterase-deficiency/',
    'https://www.ncbi.nlm.nih.gov/books/NBK537168/'
  ]
};

RX_BODY['vecuronium'] = {
  what: {
    ar: 'الفيكورونيوم مُرخٍ لعضلات الهيكل من فئة «حاصرات الوصل العصبي العضلي غير المُزيلة للاستقطاب»، ذو بنية ستيرويدية دون أن يكون كورتيزوناً. يُحقن في الوريد في العمليات والعناية المركّزة فقط، ويشلّ العضلات الإرادية وعضلات التنفّس مؤقتاً، ومدّة أثره متوسّطة. يمتاز بأنه أقلّ مرخيات العضلات إطلاقاً للهيستامين، وأثره على الضغط والنبض قليل. وله ترياق حديث يلتقطه من الدم هو السوغاماديكس، إلى جانب النيوستيغمين. وهو لا ينوّم ولا يسكّن الألم، فلا يُعطى إلا مع تخدير كافٍ.',
    en: 'Vecuronium is a skeletal muscle relaxant of the “non-depolarising neuromuscular blocker” class, with a steroid-like structure without being a cortisone. It is injected into a vein only in operations and intensive care, temporarily paralysing voluntary and breathing muscles, and its action is of intermediate length. It releases less histamine than any other muscle relaxant, and its effect on blood pressure and pulse is small. It has a modern reversal drug that captures it from the blood, sugammadex, alongside neostigmine. It neither induces sleep nor relieves pain, so it is given only with adequate anaesthesia.'
  },
  why: {
    ar: 'يُستعمل أثناء التخدير العام لتسهيل إدخال أنبوب التنفّس في القصبة الهوائية، ولإرخاء عضلات المريض أثناء الجراحة كي يعمل الجرّاح في جسم ساكن. ويُستعمل بدرجة أقلّ في العناية المركّزة لإحداث شلل مؤقّت يساعد على التنفّس الاصطناعي لمرضى مهدَّئين تهدئة كافية. ومن استعمالاته النادرة خارج النشرة إيقاف الرعشة الشديدة التي لا تستجيب لغيره أثناء التبريد العلاجي للجسم، مع أن أثره قد يطول في هذه الحالة. ويُستعمل كذلك في العمليات القيصرية.',
    en: 'It is used during general anaesthesia to make it easier to place a breathing tube in the windpipe and to relax the patient’s muscles during surgery so the surgeon works in a still body. It is used less often in intensive care to produce temporary paralysis that helps artificial ventilation in adequately sedated patients. A rare off-label use is stopping severe shivering that does not respond to other measures during therapeutic cooling of the body, although its effect may last longer in that setting. It is also used in caesarean sections.'
  },
  how: {
    ar: 'يطلق العصب عند نهايته مادة الأسيتيل كولين لتلتصق بمستقبلات على العضلة فتنقبض. يجلس الفيكورونيوم على هذه المستقبلات وينافس الأسيتيل كولين عليها دون أن ينشّطها، فتبقى العضلة مرتخية. ويتخلّص الجسم منه أساساً عبر الكبد والصفراء، وجزء منه عبر الكلى، ولأحد نواتجه أثر قريب من أثره، فيتراكم عند مرضى الكبد والكلى ومع الاستعمال الطويل. ويُعكس أثره بطريقتين: النيوستيغمين الذي يزيد الأسيتيل كولين ويُعطى معه دواء يمنع بطء القلب، أو السوغاماديكس الذي يحبس جزيئاته داخله فيبعدها عن العضلة.',
    en: 'The nerve releases acetylcholine at its ending to bind to receptors on the muscle so it contracts. Vecuronium sits on these receptors and competes with acetylcholine for them without activating them, so the muscle stays relaxed. The body clears it mainly through the liver and bile, with part through the kidneys, and one of its breakdown products acts much like the parent drug, so it builds up in liver and kidney disease and with long use. Its effect is reversed in two ways: neostigmine, which increases acetylcholine and is given with a drug that prevents a slow heart, or sugammadex, which traps its molecules inside itself and keeps them away from the muscle.'
  },
  effects: {
    ar: 'أهمّ ما يُخشى منه طول الضعف بعد انتهاء الحاجة إليه، خصوصاً مع الاستعمال الطويل. وبعد العملية قد يبقى أثر متبقٍّ يظهر بضعف أو صعوبة في التنفّس أو البلع أو رؤية مزدوجة، ويراقبه الفريق ويعكسه عند الحاجة. وقد يحدث تشنّج في الشعب أو تثبيط في التنفّس، ونادراً تحسّس شديد. أما هبوط الضغط وتسارع القلب فغير شائعين معه. ومع الاستعمال الطويل في العناية المركّزة، خصوصاً مع الكورتيزون وبعض المضادّات الحيوية واضطراب الأملاح، قد يحدث ضعف عضلي أو ضمور يطول بعد الخروج ويحتاج تأهيلاً.',
    en: 'The main concern is weakness lasting beyond the time it is needed, especially with long use. After the operation some residual effect may remain, showing as weakness, difficulty breathing or swallowing, or double vision, which the team monitors and reverses if needed. Airway spasm or depressed breathing may occur, and rarely severe allergy. A fall in blood pressure and a fast heart are uncommon with it. With long use in intensive care, especially together with cortisone, some antibiotics and salt imbalances, muscle weakness or wasting may develop that lasts after discharge and needs rehabilitation.'
  },
  warning: {
    ar: 'هذا الدواء يشلّ ولا ينوّم، فإن تذكّرت بعد العملية أنك كنت واعياً عاجزاً عن الحركة فأخبر الفريق ليُسجَّل. وبعد الإفاقة أخبر الممرّضة فوراً إن شعرت بضعف لا يتحسّن، أو عجز عن أخذ نفس عميق، أو صعوبة في البلع، أو رؤية مزدوجة. وإن أُعطيتِ السوغاماديكس لعكس أثره وكنتِ تستعملين وسيلة منع حمل هرمونية كالحبوب، فقد يقلّ أثرها، فاستعملي وسيلة إضافية غير هرمونية مدّة أسبوع بعد العملية واسألي الفريق هل أُعطيتِه. ومن أصابه تحسّس تحت التخدير فليحفظ اسم الدواء ويخبر به كل فريق لاحق.',
    en: 'This drug paralyses but does not induce sleep, so if after an operation you remember being awake and unable to move, tell the team so it is recorded. After waking, tell the nurse at once if you feel weakness that does not improve, cannot take a deep breath, have difficulty swallowing, or have double vision. If you were given sugammadex to reverse it and you use hormonal contraception such as the pill, its effect may be reduced, so use an additional non-hormonal method for a week after the operation and ask the team whether you received it. Anyone who has had an allergic reaction under anaesthesia should keep the drug’s name and tell every later team.'
  },
  interact: {
    ar: 'يطيل السكسينيل كولين أثره ويقوّيه إذا أُعطي قبله، فيجب أن ينتهي أثر الأول أولاً، ويجتمع أثره مع مرخيات العضلات الأخرى. وتقوّيه غازات التخدير المستنشقة، والمقادير العالية من الأمينوغليكوزيدات، ومضادّات حيوية أخرى كالباسيتراسين والتتراسيكلينات والكوليستين والبوليميكسين. ويزيده المغنيسيوم، ومنه ما يُعطى للحوامل في تسمّم الحمل، وقد يعيد الكينيدين الشلل أثناء الإفاقة، وحموضة الدم تقوّيه. والكورتيزون مع الاستعمال الطويل يرفع خطر الضعف العضلي. والسوغاماديكس الذي يعكسه يُضعف موانع الحمل الهرمونية مؤقتاً.',
    en: 'Suxamethonium prolongs and strengthens its effect if given first, so the first drug’s effect must end beforehand, and its effect adds to that of other muscle relaxants. Inhaled anaesthetic gases, high doses of aminoglycosides and other antibiotics such as bacitracin, tetracyclines, colistin and polymyxin strengthen it. Magnesium increases it, including the magnesium given to pregnant women with pre-eclampsia, quinidine may bring the paralysis back during recovery, and acidic blood strengthens it. Cortisone with long use raises the risk of muscle weakness. Sugammadex, which reverses it, temporarily weakens hormonal contraceptives.'
  },
  avoid: {
    ar: 'لا يُعطى لمن أصابه منه تحسّس شديد، ويُتجنّب أو يُحتاط معه عند اضطراب الأملاح الشديد كنقص الكالسيوم والبوتاسيوم والمغنيسيوم، وفي الوهن العضلي الوبيل ومتلازمة لامبرت إيتون وأمراض العضلات، وفي تليّف الكبد أو فشله لأن أثره يطول، وفي فشل الكلى، وفي السمنة التي يتأخّر فيها بدء أثره. ومرضى الحروق الواسعة يقاومون أثره شهوراً. ويُحتاط معه عند المسنّين. ويُستعمل بأمان في العمليات القيصرية، ولا يُعرف إن كان يصل حليب الأم. والرضّع أكثر حساسية له ويتأخّر تعافيهم، ولا تكفي البيانات لمن هم دون سبعة أسابيع.',
    en: 'It is not given to anyone who has had a severe allergy to it, and it is avoided or used with caution in severe salt imbalances such as low calcium, potassium or magnesium, in myasthenia gravis, Lambert-Eaton syndrome and muscle diseases, in liver cirrhosis or failure because its effect lasts longer, in kidney failure, and in obesity, where its onset is delayed. People with extensive burns resist its effect for months. Caution is needed in older people. It is used safely in caesarean sections, and it is not known whether it reaches breast milk. Infants are more sensitive to it and recover more slowly, and data are insufficient for those under seven weeks old.'
  },
  updated: '2026-09-11',
  src: [
    'https://www.ncbi.nlm.nih.gov/books/NBK493143/',
    'https://www.ncbi.nlm.nih.gov/books/NBK537168/',
    'https://www.nhs.uk/tests-and-treatments/general-anaesthesia/'
  ]
};
